def _esc(value) -> str:
    return _html.escape(str(value), quote=True)


def human_size(num) -> str:
    try:
        num = int(num)
        for unit in ("B", "KB", "MB", "GB"):
            if num < 1024 or unit == "GB":
                if unit == "B":
                    return f"{num:.0f} {unit}"
                return f"{num:.1f} {unit}"
            num /= 1024
        return f"{num:.1f} GB"
    except (TypeError, ValueError):
        return "0 B"


def time_ago(ts) -> str:
    try:
        import time as _time
        parsed = _time.strptime(str(ts)[:19], "%Y-%m-%d %H:%M:%S")
        then = _time.mktime(parsed)
        diff = _time.time() - then
        if diff < 60:
            return "just now"
        if diff < 3600:
            return f"{int(diff // 60)}m ago"
        if diff < 86400:
            return f"{int(diff // 3600)}h ago"
        if diff < 604800:
            return f"{int(diff // 86400)}d ago"
        return str(ts)[:10]
    except (ValueError, TypeError):
        return str(ts)[:10]


def theme_css(active_theme: str = "dark", font_size: str = "md") -> str:
    sizes = {"sm": "14px", "md": "15.5px", "lg": "17px", "xl": "18.5px"}
    root_fs = sizes.get(font_size, "15.5px")
    return (
        f"<style>html, body, .stApp {{ font-size: {root_fs}; }}"
        f"{_DARK_VARS}"
        f"{_BASE_CSS}"
        f"{_OVERFLOW_CSS}"
        "</style>"
    )


def page_header(icon: str, title: str, subtitle: str) -> str:
    return (
        '<div class="page-head"><div class="page-title">'
        f'<span class="page-icon">{icon}</span>{_esc(title)}'
        '</div><div class="page-sub">'
        f'{_esc(subtitle)}</div></div>'
    )


def metric_card(label, value, icon, hint="") -> str:
    hint_html = f'<div class="fx-hint">{_esc(hint)}</div>' if hint else ""
    return (
        '<div class="fx-metric"><div class="fx-metric-row">'
        f'<span class="fx-icon">{icon}</span>'
        f'<span class="fx-label">{_esc(label)}</span></div>'
        f'<div class="fx-value">{_esc(value)}</div>'
        f"{hint_html}</div>"
    )


def pill(kind: str, text: str, dot: bool = False) -> str:
    cls = kind if kind in {"info", "err", "warn", "ok"} else "info"
    return (
        f'<span class="pill {cls}{" dot" if dot else ""}">'
        f"{_esc(text)}</span>"
    )


def side_row(icon: str, label: str, value: str) -> str:
    return (
        '<div class="side-row"><span class="side-ico">'
        f'{icon}</span><span class="side-label">'
        f'{_esc(label)}</span><span class="side-val">'
        f'{_esc(value)}</span></div>'
    )


def side_section(title: str) -> str:
    return f'<div class="side-section">{_esc(title)}</div>'


def brand_html(name: str = "AI Coding Assistant", tagline: str = "Your AI engineering team") -> str:
    return (
        '<div class="side-brand"><div class="side-logo">&#9889;</div>'
        '<div><div class="side-name">'
        f'{_esc(name)}</div><div class="side-tag">'
        f'{_esc(tagline)}</div></div></div>'
    )


def user_chip(username: str, role: str) -> str:
    username = _esc(username)
    role = _esc(role)
    initial = (username or "?").strip()[0].upper()
    return (
        '<div class="user-chip"><div class="avatar">'
        f'{initial}</div><div><div class="user-name">'
        f'{username}</div><div class="user-role">'
        f'{role}</div></div>{pill("info", role)}</div>'
    )


def empty_state(icon: str, title: str, subtitle: str) -> str:
    return (
        '<div class="empty-hero"><div class="eh-icon">'
        f'{icon}</div><h2>'
        f'{_esc(title)}</h2><div class="eh-sub">'
        f'{_esc(subtitle)}</div></div>'
    )


def workflow_banner(stages: list, done: int) -> str:
    step_html = []
    for i, name in enumerate(stages):
        cls = "wf-step done" if i < done else "wf-step"
        check = "&#10003;" if i < done else str(i + 1)
        step_html.append(f'<span class="{cls}">{check} {_esc(name)}</span>')
    return (
        '<div class="workflow-banner">'
        f"{pill('ok', '&#10003; Workflow completed', dot=True)}"
        f'<div class="wf-steps">{"".join(step_html)}</div></div>'
    )


def copy_button(text: str) -> str:
    import base64
    token = base64.b64encode(str(text).encode("utf-8")).decode("ascii")
    # No inline onclick: Streamlit's markdown renderer converts HTML event
    # attributes into React props and rejects string handlers (React error
    # #231), so the handler never reaches the DOM. The bridge script
    # (copy_js) listens on the document instead and acts on .uf-copy clicks.
    return (
        '<button class="uf-copy" '
        f'data-b64="{token}">Copy</button>'
    )



def copy_js() -> str:
    # Must be injected with st.html(..., unsafe_allow_javascript=True):
    # <script> tags inside st.markdown are inert, and inline onclick is
    # stripped by the markdown renderer, so the copy buttons would be dead.
    return "\n    <script>\n    function ufB64ToText(b64) {\n        var bin = atob(b64);\n        var bytes = new Uint8Array(bin.length);\n        for (var i = 0; i < bin.length; i++) { bytes[i] = bin.charCodeAt(i); }\n        return new TextDecoder('utf-8').decode(bytes);\n    }\n    function ufCopy(b64, btn) {\n        var txt;\n        try { txt = ufB64ToText(b64); } catch(e) { txt = b64; }\n        function done() {\n            if (btn) { btn.textContent = '✓ Copied';\n                setTimeout(function(){ btn.textContent = 'Copy'; }, 1600); }\n        }\n        if (navigator.clipboard && window.isSecureContext) {\n            navigator.clipboard.writeText(txt).then(done, function(){\n                try { window.prompt('Copy to clipboard:', txt); } catch(e) {}\n            });\n        } else {\n            var ta = document.createElement('textarea');\n            ta.value = txt; document.body.appendChild(ta); ta.select();\n            try { document.execCommand('copy'); } catch(e) {}\n            document.body.removeChild(ta); done();\n        }\n    }\n    // Guard: st.html re-executes this script on every rerun, so attach the\n    // delegated listener only once (duplicates would copy N times per click).\n    if (!window.__ufCopyBound) {\n        window.__ufCopyBound = true;\n        document.addEventListener('click', function (e) {\n            var btn = e.target && e.target.closest ? e.target.closest('.uf-copy') : null;\n            if (!btn) return;\n            ufCopy(btn.getAttribute('data-b64'), btn);\n        });\n    }\n    </script>\n    "



def auth_css() -> str:
    return '\n<style>\n/* Center a narrow, tall column with breathing room (vertically centered). */\n.block-container {\n    max-width: 520px !important;\n    padding-top: 4.5vh !important;\n    padding-bottom: 2rem !important;\n}\n\n/* Ambient glow blobs behind the card - soft, not distracting. */\n[data-testid="stAppViewContainer"]::before {\n    content: ""; position: fixed; z-index: 0; pointer-events: none;\n    width: 560px; height: 560px; left: -180px; top: -180px;\n    background: radial-gradient(circle, rgba(139,92,246,.22), transparent 65%);\n    filter: blur(70px);\n}\n[data-testid="stAppViewContainer"]::after {\n    content: ""; position: fixed; z-index: 0; pointer-events: none;\n    width: 480px; height: 480px; right: -160px; bottom: -160px;\n    background: radial-gradient(circle, rgba(168,85,247,.16), transparent 65%);\n    filter: blur(70px);\n}\n.block-container { position: relative; z-index: 1; }\n\n/* Animations */\n@keyframes authFadeUp { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }\n@keyframes authSpin { to { transform: rotate(360deg); } }\n\n/* ---------- Hero (logo + name + subtitle) ---------- */\n.auth-hero { text-align: center; margin: 0 0 1.3rem; animation: authFadeUp .45s ease both; }\n.auth-hero-logo {\n    width: 64px; height: 64px; margin: 0 auto 14px; border-radius: 20px;\n    background: var(--grad); display: flex; align-items: center; justify-content: center;\n    font-size: 30px; box-shadow: 0 14px 40px rgba(124,58,237,.5);\n    animation: ufFloat 4s ease-in-out infinite;\n}\n.auth-hero-name { font-size: 1.65rem; font-weight: 820; letter-spacing: -.025em; }\n.auth-hero-sub { color: var(--muted); font-size: .92rem; margin-top: 6px; }\n\n/* ---------- Auth card (Streamlit bordered container) ---------- */\n/* Streamlit >= 1.58 renders st.container(border=True) as a stVerticalBlock\n   with data-test-scroll-behavior="normal"; scope the card to the one that\n   wraps the login/signup form (unique on this page). */\n[data-testid="stVerticalBlock"][data-test-scroll-behavior="normal"]:has([data-testid="stForm"]) {\n    background: linear-gradient(180deg, rgba(26,22,44,.82), rgba(16,14,28,.86)) !important;\n    border: 1px solid rgba(196,181,253,.14) !important;\n    border-radius: 24px !important;\n    padding: 2rem 1.9rem 1.7rem !important;\n    box-shadow: 0 26px 80px rgba(2,0,14,.6), 0 0 0 1px rgba(168,85,247,.05),\n                inset 0 1px 0 rgba(255,255,255,.05) !important;\n    backdrop-filter: blur(18px) !important;\n    animation: authFadeUp .5s .05s ease both !important;\n}\n\n/* The email form inside the card loses its own box (the card is the box). */\n[data-testid="stForm"] {\n    background: transparent !important; border: none !important;\n    box-shadow: none !important; border-radius: 0 !important; padding: 0 !important;\n}\n\n/* Card heading */\n.auth-card-head { text-align: center; margin: 0 0 1.5rem; }\n.auth-card-head h2 { font-size: 1.35rem; font-weight: 800; margin: 0 0 4px; letter-spacing: -.02em; }\n.auth-card-head p { color: var(--muted); font-size: .88rem; margin: 0; }\n\n/* ---------- Floating-label inputs ---------- */\n[data-testid="stTextInput"] { position: relative; margin-bottom: .15rem; }\n[data-testid="stTextInput"] label {\n    position: absolute; left: 15px; top: 50%; transform: translateY(-50%);\n    margin: 0; padding: 0 5px; font-size: .93rem; font-weight: 500;\n    color: var(--muted); line-height: 1; border-radius: 5px;\n    pointer-events: none; z-index: 3; transition: all .16s ease;\n    background: transparent;\n}\n[data-testid="stTextInput"]:focus-within label,\n[data-testid="stTextInput"]:has(input:not(:placeholder-shown)) label {\n    top: 0; transform: translateY(-50%);\n    font-size: .7rem; font-weight: 700; color: var(--accent2);\n    background: var(--surface);\n}\n[data-testid="stTextInput"] input {\n    height: 54px !important; padding: 20px 14px 4px !important;\n    border-radius: 13px !important; font-size: .95rem !important;\n    background: var(--surface2) !important;\n    border: 1px solid var(--border-strong) !important;\n    transition: border-color .16s ease, box-shadow .16s ease !important;\n}\n[data-testid="stTextInput"] input::placeholder { color: transparent !important; }\n[data-testid="stTextInput"]:focus-within input {\n    border-color: var(--accent2) !important;\n    box-shadow: 0 0 0 3px var(--accent-soft) !important;\n}\n\n/* ---------- Buttons ---------- */\n[data-testid="stFormSubmitButton"] > button, .stButton > button {\n    height: 50px !important; border-radius: 13px !important;\n    font-size: .95rem !important; font-weight: 650 !important;\n    transition: all .18s ease !important;\n}\n[data-testid="stFormSubmitButton"] > button:disabled, .stButton > button:disabled {\n    opacity: .55; cursor: not-allowed !important;\n    transform: none !important; box-shadow: none !important;\n}\n.stButton > button[kind="secondary"] {\n    background: var(--surface2) !important;\n    border: 1px solid var(--border-strong) !important;\n    color: var(--text) !important;\n}\n.stButton > button[kind="secondary"]:hover:not(:disabled) {\n    background: var(--surface3) !important; border-color: var(--accent) !important;\n    transform: translateY(-1px) !important; color: var(--text) !important;\n}\n.stButton > button[kind="tertiary"] {\n    background: transparent !important; border: none !important;\n    box-shadow: none !important; color: var(--muted) !important;\n    padding: 4px 8px !important; font-size: .82rem !important;\n    height: auto !important;\n}\n.stButton > button[kind="tertiary"]:hover:not(:disabled) {\n    color: var(--accent2) !important; transform: none !important;\n}\n\n/* Google button - the real Streamlit button (widget key btn_google)\n   styled as a white pill with the multicolor G. Styled directly via the\n   st-key-<key> class instead of a JS overlay: Streamlit strips inline\n   event handlers and scripts from st.markdown, so a fake button over\n   the real one renders but is unclickable. */\n[data-testid="stElementContainer"].st-key-btn_google button,\n[data-testid="stElementContainer"].st-key-btn_google a {\n    background: #ffffff !important; color: #000000 !important;\n    border: 1px solid rgba(255,255,255,.18) !important;\n    border-radius: 13px !important; height: 50px !important;\n    font-size: .95rem !important; font-weight: 600 !important;\n    display: inline-flex !important; align-items: center !important;\n    justify-content: center !important; gap: 11px !important;\n    box-shadow: 0 6px 20px rgba(2,0,14,.35) !important;\n    transition: all .18s ease !important;\n\ntext-decoration: none !important;}\n/* Streamlit renders button labels inside a <p> whose color comes from\n   the theme base CSS (near-white) - the black button color above does\n   not cascade into it, so the label must be forced dark as well or the\n   white button becomes unreadable white-on-white. */\n[data-testid="stElementContainer"].st-key-btn_google button p,\n[data-testid="stElementContainer"].st-key-btn_google button p *,\n[data-testid="stElementContainer"].st-key-btn_google a p,\n[data-testid="stElementContainer"].st-key-btn_google a p * {\n    color: #000000 !important; font-weight: 600 !important;\n}\n[data-testid="stElementContainer"].st-key-btn_google button::before,\n[data-testid="stElementContainer"].st-key-btn_google a::before {\n    content: ""; width: 20px; height: 20px; flex-shrink: 0;\n    background: url("data:image/svg+xml;base64,") center / contain no-repeat;\n}\n[data-testid="stElementContainer"].st-key-btn_google button:hover:not(:disabled),\n[data-testid="stElementContainer"].st-key-btn_google a:hover:not([aria-disabled="true"]) {\n    transform: translateY(-1px) !important;\n    box-shadow: 0 10px 28px rgba(2,0,14,.45) !important;\n}\n[data-testid="stElementContainer"].st-key-btn_google button:active:not(:disabled),\n[data-testid="stElementContainer"].st-key-btn_google a:active:not([aria-disabled="true"]) {\n    transform: translateY(0) !important;\n}\n.gbtn-hint {\n    text-align: center; color: var(--muted); font-size: .74rem;\n    margin-top: 6px;\n}\n\n/* Divider (OR) */\n.auth-divider {\n    display: flex; align-items: center; gap: 12px;\n    color: var(--muted); font-size: 12px; margin: 1.2rem 0;\n}\n.auth-divider::before, .auth-divider::after { content: ""; flex: 1; height: 1px; background: var(--border-strong); }\n\n/* Row: remember me + forgot password */\n.auth-options {\n    display: flex; align-items: center; justify-content: space-between;\n    margin: .35rem 0 .9rem;\n}\n.auth-options [data-testid="stCheckbox"] label {\n    font-size: .84rem !important; color: var(--muted) !important;\n}\n\n/* Inline error / notice (ChatGPT-style, inside the card) */\n.auth-error {\n    display: flex; align-items: flex-start; gap: 8px;\n    margin: 0 0 1rem; padding: 10px 14px; border-radius: 12px;\n    background: rgba(251,113,133,.12); border: 1px solid rgba(251,113,133,.4);\n    color: #fecdd3; font-size: .85rem; font-weight: 600;\n    animation: authFadeUp .25s ease;\n}\n.auth-notice {\n    display: flex; align-items: flex-start; gap: 8px;\n    margin: 0 0 1rem; padding: 10px 14px; border-radius: 12px;\n    background: rgba(52,211,153,.12); border: 1px solid rgba(52,211,153,.4);\n    color: #a7f3d0; font-size: .85rem; font-weight: 600;\n    animation: authFadeUp .25s ease;\n}\n.auth-busy {\n    display: flex; align-items: center; justify-content: center; gap: 9px;\n    margin: 0 0 1rem; padding: 10px; border-radius: 12px;\n    background: var(--accent-soft); border: 1px solid rgba(168,85,247,.35);\n    color: var(--accent2); font-size: .86rem; font-weight: 650;\n    animation: authFadeUp .25s ease;\n}\n.auth-busy .spin {\n    width: 15px; height: 15px; border-radius: 50%; flex-shrink: 0;\n    border: 2px solid rgba(168,85,247,.3); border-top-color: var(--accent2);\n    animation: authSpin .7s linear infinite;\n}\n\n/* Switch (create account / sign in) */\n.auth-switch {\n    text-align: center; color: var(--muted); font-size: .86rem;\n    margin-top: 1.1rem;\n}\n\n/* Guest button spacing */\n.auth-guest { margin-top: .4rem; }\n\n/* Footer */\n.auth-footer-links { margin-top: 2rem; }\n.auth-foot {\n    text-align: center; color: var(--muted); font-size: 12px;\n    margin-top: 14px;\n}\n</style>\n'
